/** Human-readable certification metadata (code → {name, description, category}). */
export const CERT_INFO: Record<string, { name: string; description: string; category: 'origin' | 'sustainability' | 'ethics' | 'heritage' }> = {
  WO: { name: 'Wine of Origin', description: 'Guarantees certified origin (appellation), vintage year, and cultivar. Administered by the Wine & Spirit Board.', category: 'origin' },
  IPW: { name: 'Integrated Production of Wine', description: 'Voluntary environmental sustainability scheme — audited vineyard & cellar practices since 1998.', category: 'sustainability' },
  WIETA: { name: 'WIETA Ethical Trade', description: "SA ethical-trade standard — fair labour, human rights, dignified working conditions.", category: 'ethics' },
  BWI: { name: 'Biodiversity & Wine Initiative', description: 'Partners estates with conservation of the Cape Floral Kingdom. "Champion" status for top performers.', category: 'sustainability' },
  OVP: { name: 'Old Vine Project (Heritage Vineyards)', description: 'World-first seal authenticating wines from vines 35+ years old; displays the planting year on the bottle.', category: 'heritage' },
  ROC: { name: 'Regenerative Organic Certified', description: 'Newer regenerative standard — soil health, animal welfare, social fairness.', category: 'sustainability' },
  FAIRTRADE: { name: 'Fairtrade', description: 'International ethical premium — community development premium per bottle.', category: 'ethics' },
};

export interface MockWine {
  id: string; slug: string; name: string; estateId: string; estateName: string;
  type: 'red' | 'white' | 'rose' | 'sparkling' | 'fortified' | 'dessert' | 'orange';
  varietals: string[]; region: string; avgStars: number; ratingCount: number;
  priceZar?: number; abv?: number; year: number; about: string; pairings: string[];
  serving: string; barcode?: string;
}

